// ResolvedCast is the resolver for the resolvedCast field. Walks
// storage.LoadRecording's resolved cast (denormalized encora cast +
// canonical performer/character rows) and decorates each entry with
// the local headshot URL the people-page SPA renders next to the
// performer name.
func (r *recordingResolver) ResolvedCast(ctx context.Context, obj *ent.Recording) ([]*ResolvedCastEntry, error) {
	loaded, err := storage.LoadRecording(ctx, r.client, obj.ID)
	if err != nil {
		return nil, fmt.Errorf("graphql: load recording %d: %w", obj.ID, err)
	}
	out := make([]*ResolvedCastEntry, 0, len(loaded.Cast))
	for _, ce := range loaded.Cast {
		entry := &ResolvedCastEntry{
			// CastEntryID is the cast-row's own primary key; the
			// LoadedRecording shape only carries Performer + Character
			// so this slot stays the performer id (the only stable
			// identifier the per-row UI needs). Surfacing the join-row
			// id is a future improvement gated on the SPA actually
			// needing it.
			CastEntryID:    ce.Performer.PerformerID,
			PerformerID:    ce.Performer.PerformerID,
			PerformerName:  ce.Performer.Name,
			PerformerSlug:  ce.Performer.Slug,
			CharacterOrder: ce.Order,
		}
		if ce.Character.CharacterID != 0 {
			cid := ce.Character.CharacterID
			entry.CharacterID = &cid
			cname := ce.Character.Name
			entry.CharacterName = &cname
		}
		if ce.Status != nil {
			label := ce.Status.Label
			entry.StatusLabel = &label
			abbrev := ce.Status.Abbreviation
			entry.StatusAbbrev = &abbrev
		}
		if r.imageCache != nil && !r.imageCache.Disabled() {
			entry.LocalHeadshotURL = r.imageCache.HeadshotURL(ce.Performer.PerformerID)
		}
		out = append(out, entry)
	}
	return out, nil
}

