// StateCounts is the resolver for the stateCounts field. Walks every
// recording for the show, runs the reconciler against each, and
// tallies the per-status counts. Inefficient for very-popular shows
// but the catalog stays small enough that the simple path is fine.
func (r *showResolver) StateCounts(ctx context.Context, obj *ent.Show) (*ShowStateCounts, error) {
	rows, err := r.client.Recording.Query().
		Where(recording.ShowID(obj.ID)).
		All(ctx)
	if err != nil {
		return nil, fmt.Errorf("graphql: list recordings for show %d: %w", obj.ID, err)
	}
	out := &ShowStateCounts{}
	for _, row := range rows {
		st, sErr := storage.LoadState(ctx, r.client, row.ID)
		if sErr != nil {
			return nil, fmt.Errorf("graphql: load state for recording %d: %w", row.ID, sErr)
		}
		switch st.Status {
		case storage.StatusSynced:
			out.Synced++
		case storage.StatusFormatMismatch:
			out.FormatMismatch++
		case storage.StatusMissing:
			out.Missing++
		case storage.StatusWanted:
			out.Wanted++
		case storage.StatusOrphan:
			out.Orphan++
		}
	}
	return out, nil
}

