// Description is the resolver for the description field. Returns the
// first non-empty `metadata.show_description` from the show's
// recordings, run through the same HTML-stripping rewriter the REST
// path uses. Empty string when no recording has a description.
func (r *showResolver) Description(ctx context.Context, obj *ent.Show) (string, error) {
	rows, err := r.client.Recording.Query().
		Where(recording.ShowID(obj.ID)).
		Order(recording.ByID()).
		Limit(showDescriptionScanLimit).
		All(ctx)
	if err != nil {
		return "", fmt.Errorf("graphql: list recordings for show %d: %w", obj.ID, err)
	}
	for _, row := range rows {
		desc := extractShowDescriptionFromRaw(row.RawJSON)
		if desc != "" {
			return stripShowDescriptionHTML(desc), nil
		}
	}
	return "", nil
}

